def cut(start, end):
    """the text from start up to and including end (both unique; end searched after start)"""
    assert P.s.count(start) == 1, "cut start: " + start[:120]
    i = P.s.index(start)
    j = P.s.index(end, i)
    assert P.s.count(end, i) >= 1
    return P.s[i:j + len(end)]


